import assert from 'node:assert/strict';
import { RoomManager } from '../server/rooms/RoomManager.js';
const rooms = new RoomManager();
const run = { mode: 'trial', attempt: 'test:1' };
const room = rooms.createRoom({ user: { id: 1, nickname: 'test' }, mode: 'pve', size: '1v1', endless: run });
assert.equal(room.endless?.attempt, run.attempt, 'Endless must use a real room with its run identity');
assert.equal(rooms.listRooms().length, 0, 'Solo endless rooms must not be joinable from the lobby');
assert.throws(() => rooms.joinRoom({ roomId: room.id, user: { id: 2 } }), /单人/);
assert.throws(() => rooms.createRoom({ user: { id: 1 }, mode: 'pve', endless: { ...run, attempt: 'other' } }), /房间/);
console.log('PASS private real-room identity / join isolation / wrong-attempt rejection');

await import('../server/battle/PvpBattle.js');
const { CardDatabase } = await import('../src/core/CardDatabase.js');
const { createEndlessRun, beginRunBattle } = await import('../src/data/EndlessAdventureRules.js');
const { normalizeEndlessRoomRun } = await import('../server/domain/EndlessRoomRun.js');
const { EndlessRoomBattle } = await import('../server/battle/EndlessRoomBattle.js');
const { installAuthorityPerformance20260905 } = await import('../server/battle/AuthorityPerformance20260905.js');
installAuthorityPerformance20260905();
const db = new CardDatabase();
for (const mode of ['trial', 'expedition']) {
  const original = createEndlessRun({ mode, seed: `room-${mode}`, starter: 'owned', ownedDeck: [{ cardId: 1, _ownedKey: 'bag:4', star: 99, craftQuality: 5 }] });
  original.phase = 'ready';
  const pending = beginRunBattle(original);
  const clean = normalizeEndlessRoomRun(pending, db, [{ slotIndex: 4, cardId: 1, star: 2, craftQuality: 3 }]);
  assert.equal(clean.roster[0].star, 2);
  assert.equal(clean.roster[0].craftQuality, 3);
  assert.throws(() => normalizeEndlessRoomRun(pending, db, []), /背包位置/);
  assert.throws(() => normalizeEndlessRoomRun({ ...pending, floor: Infinity }, db, []));
  const b = new EndlessRoomBattle({ roomId: 91, members: [{userId:1}], db, run: clean, mapId: '2' });
  assert.equal(b.engine.lootEnabled, false);
  assert.deepEqual(b.setSkillLoadout(1, [501]).loadout.filter(Boolean), []);
  b.engine.sunlight = 100;
  const before = b.engine.sunlight;
  b.snapshot(); // ACK can happen in the same server tick as a cached broadcast.
  const placed = await b.deploy(1, { cardId: 1, handIndex: 0, lane: 2, col: 0, strengthLv: 999 });
  assert.ok(placed.unit);
  assert.ok(b.snapshot().units.some(u => u.uid === placed.unit.uid), 'Same-tick deploy must invalidate the authoritative snapshot cache');
  assert.equal(b.engine.units.find(u => u.team === 'player').pvpOwnerUserId, 1);
  assert.ok(b.engine.sunlight < before);
  assert.equal(b.publicResources(1).sun, b.engine.sunlight);
  assert.ok(b.publicSkillState(1).deploySlotCooldowns[0] > 0);
  await assert.rejects(() => b.deploy(1, { cardId:1, handIndex:0, lane:1, col:0 }), /冷却|部署/);
  await assert.rejects(() => b.deploy(2, { cardId:1, handIndex:0, lane:1, col:0 }));
  await assert.rejects(() => b.deploy(1, { cardId:2, handIndex:0, lane:1, col:0 }));
  for (let i=0;i<210;i++) b.tick(1/30);
  assert.ok(b.engine.units.some(u => u.team === 'enemy'), 'server spawns the endless encounter');
  b.engine.enemyHeroHp = 0;
  b.tick(1/30);
  assert.equal(b.status, 'finished');
  assert.equal(b.snapshot().endless.result.attempt, clean.attempt);
  assert.equal(b.snapshot().endless.result.won, true);
  console.log('PASS', mode, 'server-owned instance, resources, cooldown, waves, authoritative result');
}
const { recordCardObtainReceipt } = await import('../src/core/CardObtainReceipt.js');
const events = [];
const capture = (event, data) => events.push({ event, ...data });
recordCardObtainReceipt({ ok:true, cards:[{cardId:82},{cardId:1},{cardId:82}] }, capture);
recordCardObtainReceipt({ ok:true, cardInventory:{cards:[{cardId:82}]} }, capture);
recordCardObtainReceipt({ ok:false, cards:[{cardId:82}] }, capture);
assert.equal(events.length, 3);
assert.equal(events.filter(e => e.cardId === 82).length, 2);
console.log('PASS egg receipts / no obtain on inventory hydration or failed response');
